-- Import the authoritative SIMS tag catalog (301 rows captured 2026-08-20).
-- SIMS UUIDs are preserved as local tag IDs so data_slice_tag references remain stable.
ALTER TABLE tag ADD COLUMN IF NOT EXISTS category_id VARCHAR(36);
ALTER TABLE tag ADD COLUMN IF NOT EXISTS category_path VARCHAR(500);
ALTER TABLE tag ADD COLUMN IF NOT EXISTS source VARCHAR(20) NOT NULL DEFAULT 'sims';
-- SIMS allows the same display name in different categories.
ALTER TABLE tag DROP CONSTRAINT IF EXISTS uk_tag_name;
CREATE UNIQUE INDEX IF NOT EXISTS uk_tag_category_name ON tag(category_id, name);

DELETE FROM data_slice_tag WHERE tag_id IN ('tag-004', 'tag-005', 'tag-010', 'tag-011');
DELETE FROM tag WHERE id IN ('tag-004', 'tag-005', 'tag-010', 'tag-011');

ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, description=EXCLUDED.description, rule_expr=EXCLUDED.rule_expr, category_id=EXCLUDED.category_id, category_path=EXCLUDED.category_path, source=EXCLUDED.source;
